; =============================================================================
; BANK $6A - NEW SPECIES DATA (Phase N; S105 G3: ids 221..239)
; =============================================================================
; S105 (P3.9b): hand-kept mechanism (NewSpeciesInfoCopy); slots 0-18 (ids
; 221-239, 43 bytes each) are the compiler region ns_info = project.json custom.species[].info (editor2/
; core/species.py). Before S105: generated by tools/build_new_species.py from
; extracted/new_species.json (that emit path is retired).
;
; Reached from the bank $03 info-loader fork via `ld hl,$6a00; rst $10`
; (entry 0). The far-copy routine runs IN this bank (so the high table at
; $4000-$7FFF is mapped), reads $DA31 (species id >= 221), and copies the
; 43-byte info entry for (id-221) into DE (= $DA33, preserved across rst $10).
; Mul8x8To16 lives in ROM0 so it is callable here without a bank switch.
; =============================================================================

SECTION "ROM Bank $06A", ROMX[$4000], BANK[$6A]
    db $6A                            ; bank self-ID at $4000

; rst-$10 entry table at $4001 (HL=$6a00 dispatches entry 0)
    dw NewSpeciesInfoCopy

; -----------------------------------------------------------------------------
; NewSpeciesInfoCopy - copy a new-species 43-byte info entry to DE (=$DA33).
; In: $DA31 = species id (>=221), DE = dest. Mirrors the vanilla copy loop.
; -----------------------------------------------------------------------------
NewSpeciesInfoCopy:
    ld a, [wTempSpeciesId]            ; $DA31 = species id (>=221)
    sub $dd                           ; index = id - 221 (S105 G3; was $e0 = 224)
    ld c, $2b                         ; 43 = entry size
    call Mul8x8To16                   ; HL = index * 43
    ld bc, NewSpeciesHighInfoTable    ; + high table base (this bank)
    add hl, bc
    ld b, $2b                         ; copy 43 bytes
.copy:
    ld a, [hl+]
    ld [de], a
    inc de
    dec b
    jr nz, .copy
    ret

; -----------------------------------------------------------------------------
; NewSpeciesHighInfoTable - 32 slots x 43 bytes, indexed (species_id - 221).
; Slots 0-18 = ids 221-239 (compiler region ns_info; an undeclared id is 43
; zero bytes). Slots 19-31 (ids 240-252) are never read: no species >= 240
; can exist (seen bits / breeding family codes / router wrap — S105 G3).
; -----------------------------------------------------------------------------
NewSpeciesHighInfoTable:
; @BUILD_PROJECT BEGIN ns_info
; --- slot 0: species 221 (empty) ---
    ds 43, $00
; --- slot 1: species 222 (empty) ---
    ds 43, $00
; --- slot 2: species 223 (empty) ---
    ds 43, $00
; --- slot 3: species 224 (Gorbunok; custom.species) ---
    db $00, $28, $02, $02, $01, $00, $15, $1A, $33, $0B, $04, $08, $0D, $11, $0B, $00, $00, $00, $02, $02, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $02, $02, $02, $02, $02, $00, $00
; --- slot 4: species 225 (empty) ---
    ds 43, $00
; --- slot 5: species 226 (empty) ---
    ds 43, $00
; --- slot 6: species 227 (empty) ---
    ds 43, $00
; --- slot 7: species 228 (empty) ---
    ds 43, $00
; --- slot 8: species 229 (empty) ---
    ds 43, $00
; --- slot 9: species 230 (empty) ---
    ds 43, $00
; --- slot 10: species 231 (empty) ---
    ds 43, $00
; --- slot 11: species 232 (empty) ---
    ds 43, $00
; --- slot 12: species 233 (empty) ---
    ds 43, $00
; --- slot 13: species 234 (empty) ---
    ds 43, $00
; --- slot 14: species 235 (empty) ---
    ds 43, $00
; --- slot 15: species 236 (empty) ---
    ds 43, $00
; --- slot 16: species 237 (empty) ---
    ds 43, $00
; --- slot 17: species 238 (empty) ---
    ds 43, $00
; --- slot 18: species 239 (empty) ---
    ds 43, $00
; @BUILD_PROJECT END ns_info
    ds 13 * 43, $00                   ; slots 19-31 (ids 240-252): never read
